  'match.explanation': 'සම්ප්‍රදායික අෂ්ටකූට පද්ධතිය (වර්ණ, වශ්‍ය, තාරා, යෝනි, ග්‍රහ මෛත්‍රී, ගණ, භකූට, නාඩි) අනුව 36 න් ලකුණු දෙන අතර මංගලික/භකූට/නාඩි දෝෂ ද පරීක්ෂා කරයි. නිවැරදි උපන් වේලාවන් අවශ්‍යයි.',
