  // Plain-words verdict banner
  'match.dial.caption': 'සම්ප්‍රදායික ලකුණු — පෙරහනක් මිස ශ්‍රේණියක් නොවේ',
  'match.dial.aria': 'සම්ප්‍රදායික ලකුණු ගණන: 36 න් {n}',
  'match.headline.clear': 'මෙම ගැලපීමේ සෑම ස්තරයක්ම පැහැදිලිව කියවේ — ස්වභාවයෙන්, නැකැත් වලින් සහ ව්‍යුහයෙන් කේන්දර දෙක එකිනෙකට සහාය දෙයි.',
  'match.headline.mostlyClear': 'බොහෝ ස්තර මෙම යුගලයට සහාය දෙයි. එක් අංශයක් අවධානය ඉල්ලයි — පහත සලකුණු කළ කාඩ්පත එය කුමක්දැයි කියයි.',
  'match.headline.oneArea': 'ස්තර එක් අංශයක එකඟ නොවේ. එම නොගැලපීම මෙම වාර්තාවේ වඩාත්ම ප්‍රයෝජනවත් දෙයයි — සලකුණු කළ කාඩ්පත මුලින්ම කියවන්න.',
  'match.headline.severalAreas': 'අංශ කිහිපයක සැලකිලිමත් විය යුතු කරුණු මතු වේ. පහත සලකුණු කළ එක් එක් කාඩ්පත කියවන්න — ඝර්ෂණය කුමක්ද සහ එය සමනය කරන දේ ඒවා කියයි.',
