  'legal.welcome.heroBody': 'TryTellMe ගණනය කරන ජ්‍යොතිෂ කේන්දර පදනම් වන්නේ තාරකා විද්‍යාත්මක ගණනය කිරීම් මතය. මෙය වෛද්‍ය, නීතිමය, මූල්‍ය හෝ මනෝවිද්‍යාත්මක උපදෙසක් නොවේ — වෘත්තීය උපදේශනයකට ආදේශකයක් ද නොවේ.',
  'legal.welcome.point1.label': 'වෘත්තීය උපදෙසක් නොවේ',
  'legal.welcome.point1.body': 'වෛද්‍ය, නීතිමය, මූල්‍ය, මනෝවිද්‍යාත්මක හෝ වැදගත් ජීවිත තීරණ සඳහා මෙය භාවිත නොකරන්න. සුදුසු වෘත්තිකයෙකුගෙන් උපදෙස් ලබා ගන්න.',
  'legal.welcome.point2.label': 'කිසිදු සහතිකයක් නැත — පවතින ආකාරයෙන්ම',
  'legal.welcome.point2.body': 'ජ්‍යොතිෂය විද්‍යාත්මකව තහවුරු කර නොමැත. ගණනය කිරීම් වැරදි විය හැක. නිරවද්‍යතාව, විශ්වසනීයත්වය හෝ යෝග්‍යතාව පිළිබඳ කිසිදු සහතිකයක් නොදේ.',
  'legal.welcome.point3.label': 'වගකීම් සීමා කිරීම සහ අත්හැරීම',
  'legal.welcome.point3.body': 'ඔබ මෙම සේවාව භාවිත කරන්නේ ඔබේම අවදානම මතය. නීතියෙන් ඉඩ දෙන උපරිම ප්‍රමාණයට නිර්මාපකයෝ වගකීමෙන් නිදහස් වෙති — එවැනි හිමිකම් ඔබ අත්හරියි.',
  'legal.welcome.point4.label': 'ඔබේ දත්ත පෞද්ගලිකයි',
  'legal.welcome.point4.body': 'සියල්ල ඔබේ බ්‍රව්සරය තුළම දේශීයව සිදුවේ. උපන් විස්තර අප එකතු නොකරමු, ගබඩා නොකරමු, කිසිදු තැනකට යවන්නේ ද නැත.',
  'legal.welcome.termsLink': 'සම්පූර්ණ සේවා කොන්දේසි',
  'legal.welcome.privacyLink': 'පෞද්ගලිකත්ව ප්‍රතිපත්තිය',
  'legal.welcome.accept': 'කියවා එකඟ වෙමි — ඉදිරියට',
  'legal.welcome.acceptNote': 'ඉදිරියට යාමෙන් ඔබ සේවා කොන්දේසි සහ වියාචනය පිළිගනියි.',

  'disclaimer.title': 'ඉදිරියට යාමට පෙර',
  'disclaimer.heroTitle': 'ඔබේ අනාගතය තරුවල ලියැවී නැත.',
  'disclaimer.heroBody': 'ඔබේ ජීවිතයේ කතුවරයා ඔබමයි. මෙය ඇතුළු කිසිදු අනාවැකි ක්‍රමයකට ඔබ කවුරුන්ද, කුමක් වන්නේද යන්න තීරණය කළ නොහැක.',
  'disclaimer.point1.label': 'කුතුහලය සහ ආත්ම විමර්ශනය සඳහා පමණි',
  'disclaimer.point1.body': 'කේන්දර පදනම් වන්නේ තාරකා විද්‍යාත්මක ගණනය කිරීම් මතය. සැබෑ තීරණ සඳහා මාර්ගෝපදේශයක් නොවේ.',
  'disclaimer.point2.label': 'ඔබේ මාර්ගය තීරණය කරන්නේ ඔබේ තේරීම්ය',
  'disclaimer.point2.body': 'ජීවිතය හැඩගස්වන්නේ වෙහෙස මහන්සිය, සම්බන්ධතා සහ නොසැලෙන ධෛර්යයයි — ග්‍රහ කාල නොවේ.',
  'disclaimer.point3.label': 'වෘත්තීය උපදෙසක් නොවේ',
  'disclaimer.point3.body': 'වෛද්‍ය, මූල්‍ය, මනෝවිද්‍යාත්මක හෝ නීතිමය උපදෙස් සඳහා ආදේශකයක් නොවේ.',
  'disclaimer.accept': 'තේරුම් ගත්තා — ඉදිරියට',
  'disclaimer.acceptNote': 'මෙම දැනුම්දීම මෙම උපාංගයේ නැවත නොපෙන්වයි.',

  'privacy.title': 'ඔබේ දත්ත ඔබේ උපාංගයේම',
  'privacy.bodyGenerate': 'සියල්ල බ්‍රව්සරය තුළම දේශීයව සිදුවේ. ඔබ ඇතුළත් කරන කිසිවක් සේවාදායකයකට නොයයි, ගබඩා ද නොවේ.',
  'privacy.bodyLoad': 'මෙම මෙවලම ක්‍රියා කරන්නේ ඔබේ බ්‍රව්සරය තුළම ය. අප කිසිදු දත්තයක් එකතු නොකරමු, ගබඩා නොකරමු, කිසිදා යවන්නේ ද නැත.',
  'privacy.dismiss': 'වසන්න',

  'cookies.title': 'නිර්නාමික පිවිසුම් සංඛ්‍යාලේඛන',
  'cookies.body': 'පිවිසුම් ගණන් කිරීමට අප Google Analytics භාවිත කරමු. ඔබේ උපන් විස්තර කිසිදු තැනකට නොයයි — මනිනු ලබන්නේ අඩවි භාවිතය පමණි. ප්‍රතික්ෂේප කළත් යෙදුම සාමාන්‍ය ලෙසම ක්‍රියා කරයි.',
  'cookies.accept': 'සංඛ්‍යාලේඛනවලට ඉඩ දෙන්න',
  'cookies.decline': 'එපා',

  'match.experimental.title': 'පරීක්ෂණාත්මක අංගයකි',
  'match.experimental.heroTitle': 'කේන්දර ගැලපීම තවම සංවර්ධනය වෙමින් පවතී.',
  'match.experimental.heroBody': 'පරීක්ෂණාත්මකයි — ලකුණු සහ දෝෂ ගණනය අසම්පූර්ණ හෝ සාවද්‍ය විය හැක. ගවේෂණයට පමණි; සැබෑ සම්බන්ධතා තීරණ සඳහා නොවේ.',
  'match.experimental.accept': 'තේරුණා — ඉදිරියට',

