  'ashtakavarga.howTo': 'ഓരോ രാശിക്കും ഓരോ ഗ്രഹത്തിനും 0–8 പിന്തുണാ പോയിന്റുകൾ (ബിന്ദുക്കൾ) ലഭിക്കുന്നു. ഉയർന്ന സംഖ്യകൾ ആ രാശി ഭരിക്കുന്ന ജീവിത മേഖലകൾ കൂടുതൽ എളുപ്പത്തിൽ ഒഴുകുന്നു എന്നർത്ഥമാക്കുന്നു; താഴ്ന്ന സംഖ്യകൾക്ക് കൂടുതൽ പരിശ്രമം വേണം.',
  'ashtakavarga.plainTitle': 'ഇത് നിങ്ങൾക്ക് എന്താണ് അർത്ഥമാക്കുന്നത്',
  'ashtakavarga.plainBest': 'നിങ്ങളുടെ ഏറ്റവും ശക്തമായ രാശി {sign} ({n}/56) ആണ് — ഈ രാശിയുടെ കാര്യങ്ങൾ സുഗമമായി നടക്കാൻ പ്രവണത കാണിക്കുന്നു.',
  'ashtakavarga.plainWorst': 'നിങ്ങളുടെ ഏറ്റവും വെല്ലുവിളി നിറഞ്ഞ രാശി {sign} ({n}/56) ആണ് — ഇവിടെ അധിക പരിശ്രമം പ്രതീക്ഷിക്കുക.',
  'ashtakavarga.plainPlanetStrong': '{planet} അത് ഇരിക്കുന്നിടത്ത് നന്നായി പിന്തുണയ്ക്കപ്പെടുന്നു ({n}/8) — അതിന്റെ വിഷയങ്ങൾ ({theme}) നിങ്ങൾക്ക് അനുകൂലമായി പ്രവർത്തിക്കുന്നു.',
  'ashtakavarga.plainPlanetWeak': '{planet}-ന് അത് ഇരിക്കുന്നിടത്ത് കുറച്ച് പിന്തുണ മാത്രമേ ഉള്ളൂ ({n}/8) — അതിന്റെ വിഷയങ്ങൾക്ക് ({theme}) ക്ഷമ ആവശ്യമായി വരാം.',
