  'varga.whatIsVarga': 'ഒരു വർഗ ചാർട്ട് നിങ്ങളുടെ ജനന ചാർട്ട് എടുത്ത് ജീവിതത്തിന്റെ ഒരു ഭാഗം വലുതാക്കിക്കാണിക്കുന്നു. അതേ ഒമ്പത് ഗ്രഹങ്ങൾ ആ മേഖലയിൽ മാത്രം അവ എങ്ങനെ പെരുമാറുന്നു എന്ന് കാണിക്കാൻ പുനഃക്രമീകരിക്കപ്പെടുന്നു — അതിനാൽ പണ ചാർട്ട് ശക്തമായി കാണപ്പെടുമ്പോൾ പഠന ചാർട്ട് പ്രയാസകരമായി കാണപ്പെടാം. താഴെ ഒരു ചാർട്ട് തിരഞ്ഞെടുക്കുക, എന്നിട്ട് ഗ്രിഡിലെ ഏതെങ്കിലും ബോക്സ് ടാപ്പ് ചെയ്ത് അതിന്റെ അർത്ഥത്തെക്കുറിച്ചുള്ള ലളിതമായ വായന നേടുക.',
