  'match.headline.clear': 'ഈ പൊരുത്തത്തിന്റെ എല്ലാ പാളികളും വ്യക്തമായി വായിക്കുന്നു — രണ്ട് ചാർട്ടുകളും സ്വഭാവത്തിലും നക്ഷത്രങ്ങളിലും ഘടനയിലും പരസ്പരം പിന്തുണയ്ക്കുന്നു.',
  'match.headline.mostlyClear': 'മിക്ക പാളികളും ഈ ജോടിയെ പിന്തുണയ്ക്കുന്നു. ഒരു മേഖലയ്ക്ക് ശ്രദ്ധ ആവശ്യമാണ് — താഴെയുള്ള അടയാളപ്പെടുത്തിയ കാർഡ് ഏതെന്ന് പറയുന്നു.',
