  // Legal & modals
  'legal.welcome.title': 'തുടരുന്നതിന് മുമ്പ് ദയവായി വായിക്കുക',
  'legal.welcome.subtitle': 'നിരാകരണം · സേവന നിബന്ധനകൾ · ബാധ്യതാ ഒഴിവാക്കൽ',
  'legal.welcome.heroTitle': 'വിനോദത്തിനും വിവരത്തിനും മാത്രം.',
  'legal.welcome.heroBody': 'TryTellMe ജ്യോതിശാസ്ത്ര കണക്കുകൂട്ടലുകളിൽ നിന്ന് ജ്യോതിഷ ചാർട്ടുകൾ സൃഷ്ടിക്കുന്നു. ഈ ഫലം വൈദ്യ, നിയമ, സാമ്പത്തിക, മാനസിക ഉപദേശമല്ല, പ്രൊഫഷണൽ കൺസൾട്ടേഷന് പകരമായി ഉപയോഗിക്കരുത്.',
  'legal.welcome.point1.label': 'പ്രൊഫഷണൽ ഉപദേശമല്ല',
  'legal.welcome.point1.body': 'വൈദ്യ, നിയമ, സാമ്പത്തിക, മാനസിക, അല്ലെങ്കിൽ മറ്റ് പ്രധാന ജീവിത തീരുമാനങ്ങൾക്കായി ഈ ഉപകരണം ഒരിക്കലും ഉപയോഗിക്കരുത്. എപ്പോഴും യോഗ്യതയുള്ള ഒരു പ്രൊഫഷണലിനെ സമീപിക്കുക.',
  'legal.welcome.point2.label': 'ഗ്യാരണ്ടികളില്ല — "അസ് ഈസ്" നൽകുന്നത്',
  'legal.welcome.point2.body': 'ജ്യോതിഷം ശാസ്ത്രീയമായി സാധൂകരിക്കപ്പെട്ടിട്ടില്ല. കണക്കുകൂട്ടലുകളിൽ പിഴവുകൾ ഉണ്ടാകാം. കൃത്യതയ്ക്കോ വിശ്വാസ്യതയ്ക്കോ ഏതെങ്കിലും ആവശ്യത്തിനുള്ള അനുയോജ്യതയ്ക്കോ ഞങ്ങൾ ഒരു ഗ്യാരണ്ടിയും നൽകുന്നില്ല.',
  'legal.welcome.point3.label': 'ബാധ്യതാ പരിമിതിയും ഒഴിവാക്കലും',
  'legal.welcome.point3.body': 'നിങ്ങളുടെ സ്വന്തം അപകടസാധ്യതയിലാണ് ഈ സേവനം ഉപയോഗിക്കുന്നത്. നിയമം അനുവദിക്കുന്ന പരമാവധി പരിധി വരെ, ഇത് ഉപയോഗിക്കുന്നതിൽ നിന്ന് ഉണ്ടാകുന്ന ഏതെങ്കിലും നഷ്ടം, ദോഷം, അല്ലെങ്കിൽ തീരുമാനത്തിന് സ്രഷ്ടാക്കൾ ബാധ്യസ്ഥരല്ല, അത്തരം അവകാശവാദങ്ങൾ നിങ്ങൾ ഒഴിവാക്കുന്നു.',
  'legal.welcome.point4.label': 'നിങ്ങളുടെ ഡാറ്റ സ്വകാര്യമായി തുടരുന്നു',
  'legal.welcome.point4.body': 'എല്ലാ കണക്കുകൂട്ടലുകളും നിങ്ങളുടെ ബ്രൗസറിൽ പ്രാദേശികമായി പ്രവർത്തിക്കുന്നു. നിങ്ങൾ നൽകുന്ന ജനന വിവരങ്ങൾ ഞങ്ങൾ ശേഖരിക്കുകയോ സൂക്ഷിക്കുകയോ കൈമാറുകയോ ചെയ്യുന്നില്ല.',
  'legal.welcome.termsLink': 'പൂർണ്ണ സേവന നിബന്ധനകൾ',
  'legal.welcome.privacyLink': 'സ്വകാര്യതാ നയം',
  'legal.welcome.accept': 'ഞാൻ വായിച്ച് സമ്മതിക്കുന്നു — തുടരുക',
  'legal.welcome.acceptNote': 'തുടരുന്നതിലൂടെ നിങ്ങൾ സേവന നിബന്ധനകൾ അംഗീകരിക്കുകയും ഈ നിരാകരണം അംഗീകരിക്കുകയും ചെയ്യുന്നു.',

  'disclaimer.title': 'തുടരുന്നതിന് മുമ്പ്',
  'disclaimer.heroTitle': 'നിങ്ങളുടെ ഭാവി നക്ഷത്രങ്ങളിൽ എഴുതിയിട്ടില്ല.',
