export type TranslationKey = keyof typeof en;

export const translations: Record<Lang, Record<TranslationKey, string>> = { en, si, ta, zh, hi, ja, ko, ar, ml };

const STORED_LANGS: Lang[] = ['si', 'ta', 'zh', 'hi', 'ja', 'ko', 'ar', 'ml'];

/**
 * The deep prediction engine (lib/core) now shares this same Lang union, and
 * every one of its prose tables falls back to English for a language it
 * hasn't translated yet (the same graceful degradation this UI layer already
 * relies on) — so it's safe to just pass the UI's language straight through
 * rather than collapsing everything to 'en'.
 */
export function coreLang(lang: Lang): Lang {
  return lang;
}

/** Interpolate {key} placeholders in a translation string. */
export function interpolate(
  template: string,
  vars: Record<string, string | number>,
): string {
  return template.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? `{${k}}`));
}

export function translate(key: TranslationKey, lang?: Lang): string {
  const stored = typeof localStorage !== 'undefined' ? localStorage.getItem('trytellme_lang') : null;
  const l = lang ?? ((stored && (STORED_LANGS as string[]).includes(stored)) ? (stored as Lang) : 'en');
  return translations[l][key] ?? translations.en[key];
}
